# Generates build\cf_key.h from cf_key.txt (which is never committed).
# The key is XOR-obfuscated so it isn't a plain string in the exe. This only
# deters casual extraction; anyone determined can still recover it.
param([string]$KeyFile, [string]$OutFile)

$key = ""
if (Test-Path $KeyFile) { $key = (Get-Content -Raw $KeyFile).Trim() }
$bytes = [System.Text.Encoding]::UTF8.GetBytes($key)
$obf = for ($i = 0; $i -lt $bytes.Length; $i++) { '0x{0:x2}' -f ($bytes[$i] -bxor ((0x5A + $i * 7) -band 0xFF)) }
$list = (@($obf) + '0x00') -join ', '
$text = @"
// Generated by tools\gen_key.ps1 - do not commit.
static unsigned char wam_cf_key_obf[] = { $list };
static unsigned int wam_cf_key_len = $($bytes.Length);
"@
$existing = if (Test-Path $OutFile) { Get-Content -Raw $OutFile } else { "" }
if ($existing.Trim() -ne $text.Trim()) { Set-Content -Path $OutFile -Value $text -Encoding ascii }
if ($bytes.Length) { "embedded CurseForge key ($($bytes.Length) chars)" } else { "no cf_key.txt: building without an embedded CurseForge key" }
